/* Search a narrow window around a beat-aligned loop for a quieter, smoother join. */
(function(root){function score(channels,start,end,sr){const span=Math.max(1,Math.round(sr*.012));let click=0,energy=0;for(const ch of channels){click+=Math.abs(ch[end-1]-ch[start]);for(let i=0;i<span;i++){energy+=ch[start+i]**2+ch[end-span+i]**2}}return click/channels.length+Math.sqrt(energy/(2*span*channels.length))*.2}
function suggest(channels,start,end,sr,radiusMs=25){const length=channels[0].length,span=Math.max(1,Math.round(sr*.012)),radius=Math.round(sr*radiusMs/1000);let best={start,end,score:score(channels,start,end,sr)},original=best.score;for(let shift=-radius;shift<=radius;shift+=Math.max(1,Math.floor(sr/4000))){const a=start+shift,b=end+shift;if(a<0||b>length||a+span>=b)continue;const candidate=score(channels,a,b,sr);if(candidate<best.score)best={start:a,end:b,score:candidate}}return {...best,original,shiftMs:Math.round((best.start-start)*1000/sr*10)/10}}
const api={suggest,score};if(typeof module!=='undefined')module.exports=api;else root.PulseCut=api})(globalThis);
